import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"代码 Agent","description":"设计代码 Agent 的仓库理解、上下文选择、补丁编辑、命令执行、测试验证、Sandbox、Git 与评测闭环。","frontmatter":{"title":"代码 Agent","description":"设计代码 Agent 的仓库理解、上下文选择、补丁编辑、命令执行、测试验证、Sandbox、Git 与评测闭环。","verified_at":"2026-07-31","source":["https://git-scm.com/docs","https://docs.pytest.org/en/stable/","https://tree-sitter.github.io/tree-sitter/","https://genai.owasp.org/llmrisk/llm06-excessive-agency/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/domain-agent-architectures/coding-agent.md","filePath":"py-agent/architecture/domain-agent-architectures/coding-agent.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/domain-agent-architectures/coding-agent.md"};function l(o,a,s,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="代码-agent" tabindex="-1">代码 Agent <a class="header-anchor" href="#代码-agent" aria-label="Permalink to &quot;代码 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>代码 Agent 读取仓库、定位问题、修改文件、执行命令并用测试验证结果。它的核心产物不是聊天答案，而是可审查 Patch 和验证证据。架构必须保护用户未授权改动、Secret、宿主环境和版本历史，并允许失败后精确恢复。</p><p>本章提供代码任务的参考架构。Python 应用的目录与依赖实现见<a href="/py-agent/application/application-integration/application-structure-dependency-boundaries">应用结构与依赖边界</a>，命令和文件工具的纵深隔离见<a href="/py-agent/quality/security-governance/tool-permissions-sandbox">工具权限与 Sandbox</a>，系统化验证方法见<a href="/py-agent/quality/agent-testing/test-strategy-pyramid">测试策略与金字塔</a>。</p><h2 id="_1-任务边界" tabindex="-1">1. 任务边界 <a class="header-anchor" href="#_1-任务边界" aria-label="Permalink to &quot;1. 任务边界&quot;">​</a></h2><h3 id="_1-1-只读任务" tabindex="-1">1.1 只读任务 <a class="header-anchor" href="#_1-1-只读任务" aria-label="Permalink to &quot;1.1 只读任务&quot;">​</a></h3><p>解释代码、搜索依赖、审查和诊断。允许读取范围仍需限制，尤其是凭据、生产数据和用户目录。</p><h3 id="_1-2-修改任务" tabindex="-1">1.2 修改任务 <a class="header-anchor" href="#_1-2-修改任务" aria-label="Permalink to &quot;1.2 修改任务&quot;">​</a></h3><p>修复缺陷、实现功能、重构和文档更新。输出包括 Diff、测试和剩余风险。</p><h3 id="_1-3-执行任务" tabindex="-1">1.3 执行任务 <a class="header-anchor" href="#_1-3-执行任务" aria-label="Permalink to &quot;1.3 执行任务&quot;">​</a></h3><p>安装依赖、运行测试、构建、迁移或部署。命令权限和外部副作用逐级增强，部署/发布通常需要独立确认。</p><h3 id="_1-4-非目标" tabindex="-1">1.4 非目标 <a class="header-anchor" href="#_1-4-非目标" aria-label="Permalink to &quot;1.4 非目标&quot;">​</a></h3><p>代码 Agent 不应默认拥有生产凭据、云管理权限或任意宿主 Shell。能编辑代码不等于有权提交、推送或部署。</p><h2 id="_2-参考架构" tabindex="-1">2. 参考架构 <a class="header-anchor" href="#_2-参考架构" aria-label="Permalink to &quot;2. 参考架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task / User</span></span>
<span class="line"><span>  -&gt; Coding Agent Controller</span></span>
<span class="line"><span>      -&gt; Repository Context Service</span></span>
<span class="line"><span>      -&gt; Model / Planner</span></span>
<span class="line"><span>      -&gt; File Patch Tool</span></span>
<span class="line"><span>      -&gt; Command Sandbox</span></span>
<span class="line"><span>      -&gt; Test / Lint / Build Adapters</span></span>
<span class="line"><span>      -&gt; Git Adapter</span></span>
<span class="line"><span>      -&gt; Policy + Approval</span></span>
<span class="line"><span>      -&gt; Trace / Artifact Store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Controller 管理目标、计划、预算和停止；文件与命令工具在隔离工作区执行；Git Adapter 将版本操作限制为明确命令。</p><h2 id="_3-工作区模型" tabindex="-1">3. 工作区模型 <a class="header-anchor" href="#_3-工作区模型" aria-label="Permalink to &quot;3. 工作区模型&quot;">​</a></h2><h3 id="_3-1-根目录" tabindex="-1">3.1 根目录 <a class="header-anchor" href="#_3-1-根目录" aria-label="Permalink to &quot;3.1 根目录&quot;">​</a></h3><p>解析并固定允许的绝对根，所有路径规范化后检查仍位于根内。处理 <code>..</code>、符号链接、Junction 和挂载，不能只做字符串前缀比较。</p><h3 id="_3-2-初始状态" tabindex="-1">3.2 初始状态 <a class="header-anchor" href="#_3-2-初始状态" aria-label="Permalink to &quot;3.2 初始状态&quot;">​</a></h3><p>记录 Commit、分支、工作树状态和用户已有改动。未授权不得清理、覆盖或回退已有修改。</p><h3 id="_3-3-隔离方式" tabindex="-1">3.3 隔离方式 <a class="header-anchor" href="#_3-3-隔离方式" aria-label="Permalink to &quot;3.3 隔离方式&quot;">​</a></h3><p>可使用临时副本、Git Worktree、容器或 VM。高风险命令在 Sandbox 内运行，限制网络、CPU、内存、进程、磁盘和时间。</p><h3 id="_3-4-artifact" tabindex="-1">3.4 Artifact <a class="header-anchor" href="#_3-4-artifact" aria-label="Permalink to &quot;3.4 Artifact&quot;">​</a></h3><p>保存 Patch、命令输出摘要、测试报告和必要日志。大型构建产物不直接塞入模型上下文。</p><h2 id="_4-仓库理解" tabindex="-1">4. 仓库理解 <a class="header-anchor" href="#_4-仓库理解" aria-label="Permalink to &quot;4. 仓库理解&quot;">​</a></h2><h3 id="_4-1-先读规则" tabindex="-1">4.1 先读规则 <a class="header-anchor" href="#_4-1-先读规则" aria-label="Permalink to &quot;4.1 先读规则&quot;">​</a></h3><p>发现 <code>AGENTS.md</code>、贡献指南、README、构建文件和目录级规范。规则按作用域合并，并记录来源。</p><h3 id="_4-2-文件地图" tabindex="-1">4.2 文件地图 <a class="header-anchor" href="#_4-2-文件地图" aria-label="Permalink to &quot;4.2 文件地图&quot;">​</a></h3><p>使用文件列表、语言、包、入口和依赖建立 Repo Map。<code>rg</code> 等文本搜索定位符号引用；AST/Tree-sitter/LSP 提供语法和符号关系。</p><h3 id="_4-3-选择上下文" tabindex="-1">4.3 选择上下文 <a class="header-anchor" href="#_4-3-选择上下文" aria-label="Permalink to &quot;4.3 选择上下文&quot;">​</a></h3><p>从任务词、错误栈、符号、测试和依赖图选择少量相关文件，再扩展调用者/被调用者。全仓库一次性进入 Prompt 成本高且稀释重点。</p><h3 id="_4-4-变化感知" tabindex="-1">4.4 变化感知 <a class="header-anchor" href="#_4-4-变化感知" aria-label="Permalink to &quot;4.4 变化感知&quot;">​</a></h3><p>每次执行外部格式化、生成或用户并行修改后重新读取相关文件和状态，不能在旧快照上继续覆盖。</p><h2 id="_5-计划与定位" tabindex="-1">5. 计划与定位 <a class="header-anchor" href="#_5-计划与定位" aria-label="Permalink to &quot;5. 计划与定位&quot;">​</a></h2><p>计划包含目标文件、行为变化、测试和风险，而不是复述“先分析再实现”。修复前建立失败复现或明确验收 Oracle。</p><p>从症状沿错误栈、调用链、数据流和历史改动定位根因；不要看到相似代码就全局替换。架构较大时先画受影响边界和契约。</p><h2 id="_6-编辑协议" tabindex="-1">6. 编辑协议 <a class="header-anchor" href="#_6-编辑协议" aria-label="Permalink to &quot;6. 编辑协议&quot;">​</a></h2><h3 id="_6-1-patch" tabindex="-1">6.1 Patch <a class="header-anchor" href="#_6-1-patch" aria-label="Permalink to &quot;6.1 Patch&quot;">​</a></h3><p>优先使用上下文 Patch 表达局部修改，要求旧内容匹配，避免整文件重写覆盖用户变化。机械格式化使用项目工具并限制范围。</p><h3 id="_6-2-创建与删除" tabindex="-1">6.2 创建与删除 <a class="header-anchor" href="#_6-2-创建与删除" aria-label="Permalink to &quot;6.2 创建与删除&quot;">​</a></h3><p>创建文件前确认目录职责和命名；删除或移动先查引用、路由、构建和生成关系。破坏性操作需要更强确认。</p><h3 id="_6-3-生成代码" tabindex="-1">6.3 生成代码 <a class="header-anchor" href="#_6-3-生成代码" aria-label="Permalink to &quot;6.3 生成代码&quot;">​</a></h3><p>使用项目已有生成器和版本，不手工编辑可再生文件，除非规则要求。生成输出的广泛变化需单独审查。</p><h3 id="_6-4-diff-预算" tabindex="-1">6.4 Diff 预算 <a class="header-anchor" href="#_6-4-diff-预算" aria-label="Permalink to &quot;6.4 Diff 预算&quot;">​</a></h3><p>保持改动与任务相称，避免顺手格式化或重构无关代码。小 Diff 更易审查，但不能为小而遗漏必要测试和契约更新。</p><h2 id="_7-命令执行" tabindex="-1">7. 命令执行 <a class="header-anchor" href="#_7-命令执行" aria-label="Permalink to &quot;7. 命令执行&quot;">​</a></h2><h3 id="_7-1-工具模型" tabindex="-1">7.1 工具模型 <a class="header-anchor" href="#_7-1-工具模型" aria-label="Permalink to &quot;7.1 工具模型&quot;">​</a></h3><p>命令使用固定程序和参数数组，工作目录显式；避免把模型文本交给通用 Shell。需要 Shell 语义时提升风险级别并隔离。</p><h3 id="_7-2-权限分级" tabindex="-1">7.2 权限分级 <a class="header-anchor" href="#_7-2-权限分级" aria-label="Permalink to &quot;7.2 权限分级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>示例</th><th>控制</th></tr></thead><tbody><tr><td>只读</td><td>搜索、查看状态</td><td>工作区读权限</td></tr><tr><td>本地写</td><td>格式化、测试缓存</td><td>限定根目录</td></tr><tr><td>网络</td><td>下载依赖</td><td>域名与包源 Allowlist</td></tr><tr><td>版本控制</td><td>分支、提交</td><td>明确用户授权</td></tr><tr><td>外部副作用</td><td>推送、部署</td><td>强确认与凭据隔离</td></tr></tbody></table><h3 id="_7-3-输出" tabindex="-1">7.3 输出 <a class="header-anchor" href="#_7-3-输出" aria-label="Permalink to &quot;7.3 输出&quot;">​</a></h3><p>保存退出码、时长、截断信息和 stdout/stderr 引用。长输出摘要前保留尾部错误和可查询 Artifact，不能只告诉模型“命令失败”。</p><h2 id="_8-验证阶梯" tabindex="-1">8. 验证阶梯 <a class="header-anchor" href="#_8-验证阶梯" aria-label="Permalink to &quot;8. 验证阶梯&quot;">​</a></h2><ol><li>语法/类型或最小静态检查；</li><li>受影响单元测试；</li><li>契约/集成测试；</li><li>完整相关测试与构建；</li><li>目标环境或 UI 验收。</li></ol><p>从快速定位到广泛回归逐级运行。失败要判断是产品缺陷、环境缺失、历史失败还是不稳定测试，并保留证据。</p><h3 id="_8-1-测试生成" tabindex="-1">8.1 测试生成 <a class="header-anchor" href="#_8-1-测试生成" aria-label="Permalink to &quot;8.1 测试生成&quot;">​</a></h3><p>测试基于公开行为和真实缺陷，包含失败前可复现、修复后通过。不能只 Mock 掉正要验证的边界。</p><h3 id="_8-2-无测试项目" tabindex="-1">8.2 无测试项目 <a class="header-anchor" href="#_8-2-无测试项目" aria-label="Permalink to &quot;8.2 无测试项目&quot;">​</a></h3><p>至少运行语法、类型、构建或一个直接可观察样例，并明确未验证范围。不要声称“应当能工作”。</p><h2 id="_9-git-边界" tabindex="-1">9. Git 边界 <a class="header-anchor" href="#_9-git-边界" aria-label="Permalink to &quot;9. Git 边界&quot;">​</a></h2><p>读取状态和 Diff 是常规验证；创建分支、提交、推送和 PR 是独立外部动作，应遵循用户授权。永不丢弃来源不明改动。</p><p>提交只包含任务文件，消息说明行为。历史重写、强推和硬重置属于高破坏操作，不由 Agent 自行决定。</p><h2 id="_10-安全" tabindex="-1">10. 安全 <a class="header-anchor" href="#_10-安全" aria-label="Permalink to &quot;10. 安全&quot;">​</a></h2><h3 id="_10-1-仓库内容不可信" tabindex="-1">10.1 仓库内容不可信 <a class="header-anchor" href="#_10-1-仓库内容不可信" aria-label="Permalink to &quot;10.1 仓库内容不可信&quot;">​</a></h3><p>README、Issue、代码注释和测试数据可能包含间接 Prompt Injection。它们不能提升权限或改变工具政策。</p><h3 id="_10-2-secret" tabindex="-1">10.2 Secret <a class="header-anchor" href="#_10-2-secret" aria-label="Permalink to &quot;10.2 Secret&quot;">​</a></h3><p>不读取无关 <code>.env</code>、凭据目录和生产配置；输出、Patch 与日志进行 Secret 扫描。测试使用短期、最小权限凭据。</p><h3 id="_10-3-依赖与脚本" tabindex="-1">10.3 依赖与脚本 <a class="header-anchor" href="#_10-3-依赖与脚本" aria-label="Permalink to &quot;10.3 依赖与脚本&quot;">​</a></h3><p>安装包、构建脚本和测试可执行任意代码。在隔离环境、锁定源和有限网络下运行，检查新依赖的来源与许可证。</p><h3 id="_10-4-资源与数据" tabindex="-1">10.4 资源与数据 <a class="header-anchor" href="#_10-4-资源与数据" aria-label="Permalink to &quot;10.4 资源与数据&quot;">​</a></h3><p>限制命令时间、进程、磁盘和网络；数据库迁移和生产数据操作必须隔离。测试失败不能触发无限修复循环。</p><h2 id="_11-评测" tabindex="-1">11. 评测 <a class="header-anchor" href="#_11-评测" aria-label="Permalink to &quot;11. 评测&quot;">​</a></h2><p>数据集包含仓库 Revision、Issue、环境、允许修改、测试和隐藏验收。指标包括任务解决率、Patch 正确性、回归、Diff 范围、命令/Token、时间、安全违规和人工接受率。</p><p>必须在隔离、可重置仓库运行，防止上一个任务状态污染。隐藏测试避免 Agent 只针对可见断言硬编码，但应与公开需求一致。</p><h2 id="_12-常见误区" tabindex="-1">12. 常见误区 <a class="header-anchor" href="#_12-常见误区" aria-label="Permalink to &quot;12. 常见误区&quot;">​</a></h2><ol><li><strong>把全仓库塞进上下文</strong>：昂贵且难定位。</li><li><strong>测试通过就一定正确</strong>：测试可能不足或被错误修改。</li><li><strong>任意 Shell 是必要能力</strong>：多数动作可用受限工具表达。</li><li><strong>格式化整个仓库</strong>：淹没真实 Diff 和用户改动。</li><li><strong>能修改就能提交/部署</strong>：这些是独立权限。</li></ol><p>代码 Agent 的可靠性来自闭环：基于当前仓库证据定位，使用小而可审查的 Patch 修改，在隔离环境运行与风险相称的验证，并保留 Diff、命令和未验证范围。</p>`,78)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
